    ('9ba7c034-6aec-492e-b66e-4541ce3c987c'::uuid, 'cultural_influence', '10', '7', 'card-stats-2026-11-12b-rollback:9ba7c034-6aec-492e-b66e-4541ce3c987c:cultural_influence', 'rollback of card-stats-2026-11-12b: cultural_influence ''7'' restored on Olympia, Greece', '34ea513a7b6de7ad8562c5be42d87bf2', '[{"source": "api/cardgame/generator.py:site_card_stats", "url": "api/cardgame/generator.py", "quote": "cultural_influence = 10 from description yes, thumbnail yes, 5 content link(s), 20 image(s), source_url yes"}, {"source": "production export 07ceaa5910522703 (2026-11-12 12:30:18.70478+00)", "url": "remediation_change_log + unified_sites + card_stats (read-only)", "quote": "counterfactual: 0 journalled input value(s) put back reproduce the stored card_stats in all 59472 cells (basis: wave 2026-11-12''s own export (2026-11-12 10:36:17.26111+00))"}, {"source": "remediation_change_log:44869", "url": "remediation_change_log", "quote": "phase4:p4-0101:chunk-0001: description ''Olympia, also known as Archaia Olympia, is an ancient Greek sanctuary in Elis on the Peloponnese peninsula that served as a major Panhellenic religious center [1]. The site hosted the ancient Olympic Games every four years from the 8th century BC through the 4th century AD, making it one of the most significant athletic and religious venues in classical antiquity [1]. These games were restored internationally in 1896, reviving the tradition nearly 1,500 years after the last ancient Olympics [1].'' -> ''Olympia lies in the valley of the Alfeiós River in the western part of the Peloponnese, today around 18 km from the Gulf of Kyparissia in the Ionian Sea, but in antiquity perhaps half that distance [1]. According to Pausanias, there were over 70 temples in total, as well as treasuries, altars, statues, and other structures dedicated to many deities [1]. The first Olympic festival was organized on the site by the authorities of Elis in the 8th century BC – with tradition dating the first games at 776 BC [1]. The earliest evidence of building activity on the site dates from around 600 BC [1]. The Temple of Zeus was built mid 5th century BC [1]. The exact site was re-discovered in 1766 by the English antiquarian Richard Chandler [1]. The first major excavation of Olympia began in 1875 [1]. Important finds included sculptures from the Temple of Zeus, the Nike of Paeonius, the Hermes of Praxiteles and many bronzes [1].''"}, {"source": "remediation_change_log:104341", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_name ''1500 - 500 BC'' -> ''3000 - 1500 BC''"}, {"source": "remediation_change_log:104342", "url": "remediation_change_log", "quote": "2026-09-26d_fields-wd1-s014: period_start ''-1500'' -> ''-2300''"}, {"source": "remediation_change_log:156854", "url": "remediation_change_log", "quote": "served-image-2026-09-30-021: thumbnail_url ''https://upload.wikimedia.org/wikipedia/commons/c/cf/Ancient_Olympia%2C_Greece2.jpg'' -> ''/data/images/wiki/9ba7c034/Olympic Flame, the Start of the Olympic Torch Relay (51224124860).webp''"}, {"source": "remediation_change_log:314806", "url": "remediation_change_log", "quote": "import-hero-2026-10-05-002-010: thumbnail_url ''/data/images/wiki/9ba7c034/Olympic Flame, the Start of the Olympic Torch Relay (51224124860).webp'' -> ''/data/images/wiki/9ba7c034/Ancient_Olympia,_Greece2.webp''"}]'::jsonb),
